        "code": "- hosts: webservers\n  become: yes\n  tasks:\n    - name: Copiar config do nginx\n      template:\n        src: nginx.conf.j2\n        dest: /etc/nginx/nginx.conf\n      notify: Reiniciar nginx\n\n    - name: Copiar site config\n      copy:\n        src: site.conf\n        dest: /etc/nginx/sites-available/default\n      notify: Reiniciar nginx\n\n  handlers:\n    - name: Reiniciar nginx\n      service:\n        name: nginx\n        state: restarted"
